//!
//! Codex ships as a single executable that dispatches to helper CLIs
//! (`apply_patch`, `codex-linux-sandbox`, ...) based on `argv0`/`argv1` using
//! the "arg0 trick" (see [`codex_arg0`]). Integration test binaries want the
//! same behavior so that code under test can re-exec these helpers, but they
//! must install the arg0 aliases into a throwaway `CODEX_HOME` so they never
//! mutate the developer's real `~/.codex`.
//!
//! This crate centralizes that setup. Test crates call
//! [`configure_test_binary_dispatch`] from a `#[ctor]` static initializer,
//! passing a `classify` closure that inspects the current invocation and
//! decides what to do.
#![expect(clippy::expect_used)]

use std::ffi::OsString;
use std::path::Path;

use codex_arg0::Arg0DispatchPaths;
use codex_arg0::Arg0PathEntryGuard;
use codex_arg0::arg0_dispatch;
use tempfile::TempDir;

const CODEX_HOME_ENV_VAR: &str = "CODEX_HOME";

/// Controls what [`configure_test_binary_dispatch`] does for the current
/// process invocation. Returned by the `classify` closure.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TestBinaryDispatchMode {
    /// Dispatch via arg0 (e.g. because the process was re-exec'd as a helper
    /// CLI) and return `None`. No throwaway `CODEX_HOME` or aliases are set up.
    DispatchArg0Only,
    /// Do nothing and return `None`. Used for helper re-execs (such as the
    /// linux sandbox) that must not create another `CODEX_HOME` tempdir.
    Skip,
    /// Set up a temporary `CODEX_HOME`, install arg0 dispatch aliases into it,
    /// restore the previous `CODEX_HOME`, and return a guard.
    InstallAliases,
}

/// Keeps the throwaway `CODEX_HOME` directory and the arg0 alias PATH entry
/// alive for the lifetime of the test binary. Returned by
/// [`configure_test_binary_dispatch`] when aliases are installed.
pub struct TestBinaryDispatchGuard {
    // Field order matters for drop order: keep the PATH entry guard alive at
    // least as long as the temp dir it points into.
    arg0: Arg0PathEntryGuard,
    _codex_home: TempDir,
    _previous_codex_home: Option<OsString>,
}

impl TestBinaryDispatchGuard {
    /// Paths to the current Codex executable and helper binaries derived from
    /// the installed arg0 aliases.
    pub fn paths(&self) -> &Arg0DispatchPaths {
        self.arg0.paths()
    }
}

/// Reads `argv0`/`argv1`, calls `classify(exe_name, argv1)` to determine the
/// dispatch mode, and acts accordingly. Intended to be called from a `#[ctor]`
/// static initializer in test binaries.
///
/// The `codex_home_prefix` is used as the filename prefix for the throwaway
/// `CODEX_HOME` temporary directory created when the classify closure returns
/// [`TestBinaryDispatchMode::InstallAliases`].
pub fn configure_test_binary_dispatch<F>(
    codex_home_prefix: &str,
    classify: F,
) -> Option<TestBinaryDispatchGuard>
where
    F: FnOnce(&str, Option<&str>) -> TestBinaryDispatchMode,
{
    let mut args = std::env::args_os();
    let argv0 = args.next().unwrap_or_default();
    let exe_name = Path::new(&argv0)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("");
    let argv1 = args.next().unwrap_or_default();
    let argv1 = argv1.to_str();

    match classify(exe_name, argv1) {
        TestBinaryDispatchMode::DispatchArg0Only => {
            // Helper re-execs (e.g. the core apply_patch helper) just need to
            // run arg0 dispatch so the current process behaves like the helper.
            let _ = arg0_dispatch();
            None
        }
        TestBinaryDispatchMode::Skip => None,
        TestBinaryDispatchMode::InstallAliases => {
            let codex_home = tempfile::Builder::new()
                .prefix(codex_home_prefix)
                .tempdir()
                .expect("create throwaway CODEX_HOME for test binary dispatch");
            let previous_codex_home = std::env::var_os(CODEX_HOME_ENV_VAR);
            // `arg0_dispatch()` creates helper links under `CODEX_HOME/tmp`.
            // Point it at a test-owned temp dir so startup never mutates the
            // developer's real `~/.codex`.
            //
            // Safety: this runs from a `#[ctor]` before any test threads exist.
            unsafe {
                std::env::set_var(CODEX_HOME_ENV_VAR, codex_home.path());
            }

            let arg0 = arg0_dispatch().expect("install arg0 dispatch aliases for test binary");

            // Restore the process environment immediately so later tests
            // observe the same `CODEX_HOME` state they started with.
            //
            // Safety: still single-threaded at ctor time.
            match previous_codex_home.as_ref() {
                Some(value) => unsafe {
                    std::env::set_var(CODEX_HOME_ENV_VAR, value);
                },
                None => unsafe {
                    std::env::remove_var(CODEX_HOME_ENV_VAR);
                },
            }

            Some(TestBinaryDispatchGuard {
                arg0,
                _codex_home: codex_home,
                _previous_codex_home: previous_codex_home,
            })
        }
    }
